import socket, urllib.request, urllib.error
print('EGRESS-TEST start', flush=True)
for host in ['example.com', 'api.ecr.eu-central-1.amazonaws.com']:
    try:
        print('DNS', host, '->', socket.gethostbyname(host), flush=True)
    except Exception as e:
        print('DNS', host, 'FAILED', e, flush=True)
for url in ['https://example.com', 'https://www.google.com', 'https://api.ecr.eu-central-1.amazonaws.com']:
    try:
        urllib.request.urlopen(url, timeout=5)
        print('REACHABLE', url, flush=True)
    except urllib.error.HTTPError as e:
        print('REACHABLE', url, '(HTTP', e.code, ')', flush=True)
    except Exception as e:
        print('BLOCKED  ', url, type(e).__name__, e, flush=True)
print('EGRESS-TEST end', flush=True)
